import { createRouter, createRootRoute, createRoute } from "@tanstack/react-router"
import App from "./App"
import HomePage from "./pages/HomePage"
import NotificationPage from "./components/NotificationPage"
import TransactionsPage from "./pages/TransactionsPage"
import AccountPage from "./pages/AccountPage"
import AccountTransactionsPage from "./pages/AccountTransactionsPage"
import AccountDetailPage from "./pages/AccountDetailPage"

const rootRoute = createRootRoute({
  component: App,
})

const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/",
  component: HomePage,
})

const notificationsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/notifications",
  component: NotificationPage,
})

const transactionsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/transactions",
  component: TransactionsPage,
})

const accountRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/account",
  component: AccountPage,
})

const accountDetailRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/account/$accountNumber",
  component: AccountDetailPage,
})

const accountTransactionsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/account/transactions",
  component: AccountTransactionsPage,
})

const routeTree = rootRoute.addChildren([
  indexRoute,
  notificationsRoute,
  transactionsRoute,
  accountRoute,
  accountDetailRoute,
  accountTransactionsRoute,
])

const router = createRouter({ routeTree })

declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router
  }
}

export { router, rootRoute }

import { useState, useEffect } from "react"
import { Outlet, Link } from "@tanstack/react-router"
import { useSession } from "./lib/auth-client"
import type { Session } from "./lib/auth-client"
import { Skeleton } from "./components/ui/skeleton"
import AuthPage from "./components/AuthPage"

const linkBase =
  "relative text-sm font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"

const navItems = [
  { to: "/", label: "Home" },
  { to: "/notifications", label: "Notifications" },
  { to: "/transactions", label: "Transactions" },
  { to: "/account", label: "Account" },
] as const

export default function App() {
  const { data: session, isPending } = useSession()
  const [backendOff, setBackendOff] = useState(false)

  useEffect(() => {
    if (!isPending) return
    const timer = setTimeout(() => {
      if (typeof window !== "undefined") {
        fetch("/api/auth/session", { method: "HEAD", signal: AbortSignal.timeout(1000) }).catch(() =>
          setBackendOff(true)
        )
      }
    }, 2000)
    return () => clearTimeout(timer)
  }, [isPending])

  if (isPending && !backendOff) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-background p-8">
        <div data-testid="loading-skeleton" className="w-full max-w-sm space-y-4">
          <div className="space-y-2 text-center">
            <Skeleton className="h-8 w-3/4 mx-auto rounded-md" />
            <Skeleton className="h-4 w-1/2 mx-auto rounded-md" />
          </div>
          <div className="space-y-3 pt-4">
            <Skeleton className="h-4 w-full rounded-md" />
            <Skeleton className="h-4 w-full rounded-md" />
            <Skeleton className="h-10 w-full rounded-md" />
          </div>
        </div>
      </div>
    )
  }

  const activeSession = session ?? (backendOff
    ? ({
        user: {
          id: "dev_user",
          name: "Alex Rivera",
          email: "alex@wave.dev",
          emailVerified: true,
          createdAt: new Date(),
          updatedAt: new Date(),
        },
        session: { id: "dev_session", expiresAt: new Date(Date.now() + 86400000) },
      } as Session)
    : null)

  if (!activeSession) {
    return (
      <div className="flex min-h-screen flex-col bg-background text-foreground">
        <AuthPage />
      </div>
    )
  }

  return (
      <div className="flex min-h-screen flex-col bg-background text-foreground">
        <nav className="flex items-center gap-6 px-8 h-14 border-b border-border bg-card">
          <span className="text-base font-bold tracking-tight text-foreground mr-2">Wave</span>
          {navItems.map((item) => (
            <Link
              key={item.to}
              to={item.to}
              className={linkBase}
              activeProps={{ className: "text-foreground font-semibold after:absolute after:-bottom-[17px] after:left-0 after:right-0 after:h-[2px] after:bg-primary" }}
              inactiveProps={{ className: "text-muted-foreground hover:text-foreground" }}
            >
              {item.label}
            </Link>
          ))}
        </nav>
        <Outlet />
      </div>
  )
}

import { useEffect, useState, useCallback, useMemo } from "react"
import { Link } from "@tanstack/react-router"
import { Plus, ArrowUpRight } from "lucide-react"
import { signOut, useSession } from "../lib/auth-client"
import { Button } from "../components/ui/button"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import SectionCards from "../components/SectionCards"
import ChartAreaInteractive from "../components/ChartAreaInteractive"
import DataTable from "../components/DataTable"
import type { IWalletTransaction, WaveResponse, ITransaction } from "@/types"

type ApiResponse<T> = WaveResponse<T>

const formatBalance = (b: number) =>
  new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(b)

export default function HomePage() {
  const { data: session } = useSession()
  const user = session!.user
  const [accounts, setAccounts] = useState<IWalletTransaction[]>([])
  const [transactions, setTransactions] = useState<ITransaction[]>([])
  const [loadingAccounts, setLoadingAccounts] = useState(true)
  const [loadingTransactions, setLoadingTransactions] = useState(true)

  const userAccountIds = useMemo(() => new Set(accounts.map((a) => a.id)), [accounts])

  const fetchAccounts = useCallback(async () => {
    setLoadingAccounts(true)
    try {
      const res = await fetch(`/api/wallet/users/${user.id}/accounts`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json: ApiResponse<IWalletTransaction[]> = await res.json()
      setAccounts(json.ok ? json.data : [])
    } catch {
      setAccounts([])
    } finally {
      setLoadingAccounts(false)
    }
  }, [user.id])

  const fetchTransactions = useCallback(async () => {
    setLoadingTransactions(true)
    try {
      const res = await fetch(`/api/wallet/users/${user.id}/transactions`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json: ApiResponse<ITransaction[]> = await res.json()
      if (json.ok) {
        const sorted = json.data.sort(
          (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        )
        setTransactions(sorted)
      }
    } catch {
      setTransactions([])
    } finally {
      setLoadingTransactions(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
    fetchTransactions()
  }, [fetchAccounts, fetchTransactions])

  const totalBalance = accounts.reduce((sum, a) => sum + a.balance, 0)

  const dailyVolumes = useMemo(() => {
    const map = new Map<string, number>()
    for (const tx of transactions) {
      const day = tx.createdAt.slice(0, 10)
      map.set(day, (map.get(day) ?? 0) + Number(tx.amount))
    }
    return Array.from(map.entries())
      .map(([date, volume]) => ({ date, volume }))
      .sort((a, b) => a.date.localeCompare(b.date))
  }, [transactions])

  const recentTransactions = useMemo(() => transactions.slice(0, 10), [transactions])

  const successCount = transactions.filter((tx) => tx.status === "success").length
  const pendingCount = transactions.filter((tx) => tx.status === "pending").length
  const totalVolume = transactions.reduce((sum, tx) => sum + Number(tx.amount), 0)

  const cardData = loadingAccounts
    ? []
    : [
        {
          title: "Total Balance",
          value: formatBalance(totalBalance),
          subtitle: `${accounts.length} account${accounts.length !== 1 ? "s" : ""}`,
          trend: { value: `${accounts.length > 0 ? "+" : ""}${accounts.length}`, positive: accounts.length > 0 },
        },
        {
          title: "Transaction Volume",
          value: formatBalance(totalVolume),
          subtitle: `${transactions.length} transaction${transactions.length !== 1 ? "s" : ""}`,
        },
        {
          title: "Success Rate",
          value: transactions.length > 0 ? `${Math.round((successCount / transactions.length) * 100)}%` : "\u2014",
          subtitle: `${successCount} of ${transactions.length} succeeded`,
          trend: successCount > 0 ? { value: `${successCount}`, positive: true } : undefined,
        },
        {
          title: "Pending",
          value: String(pendingCount),
          subtitle: pendingCount === 1 ? "1 awaiting confirmation" : `${pendingCount} awaiting confirmation`,
        },
      ]

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <h1 className="text-xl font-semibold tracking-tight text-foreground">Dashboard</h1>
        <div className="flex items-center gap-3">
          <span className="text-sm text-muted-foreground">{user.email}</span>
          <Button variant="ghost" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-6xl px-8 py-8 space-y-6">
        <div className="flex items-center gap-2">
          <h2 className="text-sm font-medium text-muted-foreground">
            {new Date().getHours() < 12
              ? "Good morning"
              : new Date().getHours() < 18
                ? "Good afternoon"
                : "Good evening"
            }, {user.name}
          </h2>
        </div>

        <SectionCards data={cardData} />

        <div className="grid grid-cols-2 gap-4">
          <Link
            to="/account"
            search={{ section: "deposit" }}
            className="inline-flex items-center justify-center gap-3 rounded-xl bg-primary text-primary-foreground h-14 text-sm font-semibold transition-colors hover:opacity-90"
          >
            <Plus className="size-4" />
            Add Money
          </Link>
          <Link
            to="/account"
            className="inline-flex items-center justify-center gap-3 rounded-xl bg-surface text-foreground h-14 text-sm font-semibold transition-colors hover:bg-surface-hover border border-border"
          >
            <ArrowUpRight className="size-4" />
            Send Money
          </Link>
        </div>

        <ChartAreaInteractive data={dailyVolumes} />

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-4">
            <CardTitle className="text-sm font-medium">Recent Transactions</CardTitle>
            <Link
              to="/account/transactions"
              className="text-sm font-medium text-muted-foreground hover:text-foreground transition-colors"
            >
              View all
            </Link>
          </CardHeader>
          <CardContent className="p-0">
            <DataTable
              data={recentTransactions}
              userAccountIds={userAccountIds}
              loading={loadingTransactions}
              emptyMessage="No transactions yet. Deposit funds to get started."
            />
          </CardContent>
        </Card>
      </main>

      <footer className="flex justify-between items-center px-8 py-4 text-sm text-muted-foreground/70 border-t border-border">
        <span>Wave Payment Platform</span>
        <span>{accounts.length} account{accounts.length !== 1 ? "s" : ""}</span>
      </footer>
    </>
  )
}

import { useEffect, useState, useCallback, useMemo } from "react"
import { useParams, Link } from "@tanstack/react-router"
import { ArrowLeft, Eye, EyeOff, MoreVertical } from "lucide-react"
import { useSession } from "../lib/auth-client"
import {
  Card,
